def components(I):
    I=np.array(I);H,W=I.shape;lab=-np.ones((H,W),int);comps=[]
    for r in range(H):
        for c in range(W):
            if lab[r,c]>=0: continue
            col=I[r,c];stack=[(r,c)];cells=[]
            lab[r,c]=len(comps)
            while stack:
                a,b=stack.pop();cells.append((a,b))
                for nr,nc in nb(a,b,H,W):
                    if I[nr,nc]==col and lab[nr,nc]<0:
                        lab[nr,nc]=len(comps);stack.append((nr,nc))
            comps.append((col,cells))
    return comps

def predict2(I, maxsize=1):
    I=np.array(I);H,W=I.shape;O=I.copy()
    bg=Counter(I.flat).most_common(1)[0][0]
    comps=components(I)
    for col,cells in comps:
        if len(cells)>maxsize: continue
        if col==bg: continue
        for r,c in cells:
            cnt=Counter(I[nr,nc] for nr,nc in nb(r,c,H,W))
            others=[(cc,n) for cc,n in cnt.items() if cc!=col]
            if not others: continue
            others.sort(key=lambda x:-x[1])
            top=others[0]
            # tie-break nonbg
            cand=[cc for cc,n in others if n==top[1]]
            if len(cand)>1:
                pick=next((cc for cc in cand if cc!=bg), cand[0])
            else: pick=top[0]
            O[r,c]=pick
    return O
for ms in (1,2,3,4,8):
    print(ms,(predict2(I,ms)==O).all())
